questionvariables.text:
/* Core variables */
d: rand(5)*2+12;          /* 14,16,18,20,22 m */
theta: rand(4)*5+30;      /* 35,40,45,50 */
eye: rand(3)+2;           /* observer eye level above deck: 3 to 5 m */

/* Evaluate mathematics to floating-point decimals natively */
extra: float(d*tan(theta*%pi/180));   /* vertical drop from eye level to object */
height_total: float(eye + extra);     /* total height above sea level */

/* Display variables formatted to exactly 1 decimal place */
disp_extra: dispdp(extra, 1);
disp_height: dispdp(height_total, 1);

/* Context */
structure: rand(["lighthouse","watch tower","harbour post"]);
item: rand(["boat","boy","small raft"]);
coast: rand(["Mombasa","Kilifi","Lamu","Malindi"]);

/*------Mistakes (Calculated as explicit floats)--------*/
m1: float(extra);                         /* forgot to add eye level */
m2: float((d/sin(theta*%pi/180)) + eye);  /* used sine instead of tangent */
m3: float((d/tan(theta*%pi/180)) + eye);  /* inverted tangent ratio */
